  1	/**
  2	 * tests/builders/build-config-variables-and-partials.test.ts
  3	 *
  4	 * WP-007 — Unit Tests: Custom Variables and Config Partials
  5	 *
  6	 * Verifies all 6 behavioural Acceptance Criteria:
  7	 *
  8	 *   AC-1: BuildConfig.variables values appear in the rendered context when no
  9	 *         higher-priority source provides them.
 10	 *   AC-2: SuiteConfig.variables values override BuildConfig.variables values
 11	 *         for the same key.
 12	 *   AC-3: Persona YAML values override both SuiteConfig.variables and
 13	 *         BuildConfig.variables.
 14	 *   AC-4: _shared.yaml values override BuildConfig.variables (but are
 15	 *         overridden by persona YAML).
 16	 *   AC-5: BuildConfig.partials entries are present in the rendered template
 17	 *         output.
 18	 *   AC-6: File-based partials with the same stem name override
 19	 *         BuildConfig.partials.
 20	 *
 21	 * AC-7 (all new tests pass) and AC-8 (all existing tests continue to pass)
 22	 * are verified by running the full test suite.
 23	 *
 24	 * These tests exercise the merge wiring introduced by WP-002 (Custom Variables)
 25	 * and WP-004 (Config Partials).  They intentionally use the same public surface
 26	 * as the WP-002 / WP-004 test files — buildPersona() and buildSuite() — so that
 27	 * the acceptance criteria are demonstrably reachable through the public API.
 28	 */
 29	
 30	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
 31	import { mkdir, writeFile, rm } from 'node:fs/promises';
 32	import { tmpdir } from 'node:os';
 33	import path from 'node:path';
 34	
 35	import { buildPersona, buildSuite } from '../../src/builders/persona-builder.js';
 36	import type { BuildConfig, BuildResult } from '../../src/builders/types.js';
 37	import type { SuiteConfig } from '../../src/plugins/types.js';
 38	
 39	// ---------------------------------------------------------------------------
 40	// Temp directory lifecycle
 41	// ---------------------------------------------------------------------------
 42	
 43	let testTmpDir: string;
 44	
 45	beforeEach(async () => {
 46	  testTmpDir = path.join(
 47	    tmpdir(),
 48	    `wp007-${Date.now()}-${Math.random().toString(36).slice(2)}`,
 49	  );
 50	  await mkdir(testTmpDir, { recursive: true });
 51	});
 52	
 53	afterEach(async () => {
 54	  await rm(testTmpDir, { recursive: true, force: true });
 55	});
 56	
 57	// ---------------------------------------------------------------------------
 58	// Fixture helpers
 59	// ---------------------------------------------------------------------------
 60	
 61	/**
 62	 * Creates a minimal suite with a single persona ("agent") and returns the
 63	 * paths and SuiteConfig needed to call buildPersona() or buildSuite().
 64	 */
 65	async function createMinimalSuite(opts: {
 66	  sharedYaml?: string;
 67	  personaYaml?: string;
 68	  contentMd?: string;
 69	  /** Partial files to create in the suite's `partials/` directory */
 70	  suitePartials?: Record<string, string>;
 71	}): Promise<{
 72	  suiteDir: string;
 73	  outDir: string;
 74	  yamlPath: string;
 75	  suiteConfig: SuiteConfig;
 76	}> {
 77	  const suiteDir = path.join(testTmpDir, 'suite');
 78	  const outDir = path.join(testTmpDir, 'out');
 79	
 80	  await mkdir(path.join(suiteDir, 'meta'), { recursive: true });
 81	  await mkdir(path.join(suiteDir, 'content'), { recursive: true });
 82	  await mkdir(path.join(suiteDir, 'partials'), { recursive: true });
 83	
 84	  await writeFile(
 85	    path.join(suiteDir, 'meta', '_shared.yaml'),
 86	    opts.sharedYaml ?? 'default_version: "1.0.0"\n',
 87	  );
 88	
 89	  await writeFile(
 90	    path.join(suiteDir, 'meta', 'agent.yaml'),
 91	    opts.personaYaml ??
 92	      'name: Test Agent\nvs_file_name: agent.agent.md\ncc_file_name: agent.md\n',
 93	  );
 94	
 95	  await writeFile(
 96	    path.join(suiteDir, 'content', 'agent.md'),
 97	    opts.contentMd ?? '# {{name}}\n',
 98	  );
 99	
100	  if (opts.suitePartials) {

101	    for (const [stem, content] of Object.entries(opts.suitePartials)) {
102	      await writeFile(path.join(suiteDir, 'partials', `${stem}.md`), content);
103	    }
104	  }
105	
106	  const suiteConfig: SuiteConfig = {
107	    srcDir: suiteDir,
108	    outVscode: outDir,
109	    outClaudeCode: outDir,
110	  };
111	
112	  return {
113	    suiteDir,
114	    outDir,
115	    yamlPath: path.join(suiteDir, 'meta', 'agent.yaml'),
116	    suiteConfig,
117	  };
118	}
119	
120	/**
121	 * Builds a single persona with the supplied config and shared-meta and returns
122	 * the rendered content string.
123	 */
124	async function renderPersona(
125	  yamlPath: string,
126	  suiteConfig: SuiteConfig,
127	  config: BuildConfig,
128	  sharedMeta: Record<string, unknown> = { default_version: '1.0.0' },
129	): Promise<BuildResult> {
130	  return buildPersona(
131	    yamlPath,
132	    'test-suite',
133	    suiteConfig,
134	    sharedMeta,
135	    {},
136	    config,
137	    [],
138	    'vscode',
139	  );
140	}
141	
142	// ---------------------------------------------------------------------------
143	// AC-1: BuildConfig.variables values appear in the rendered output when no
144	//        higher-priority source provides them.
145	// ---------------------------------------------------------------------------
146	
147	describe('AC-1 — BuildConfig.variables values appear when no higher-priority source overrides them', () => {
148	  it('renders a single BuildConfig.variables value via a template placeholder', async () => {
149	    const { yamlPath, suiteConfig } = await createMinimalSuite({
150	      contentMd: '# {{name}}\nenv: {{environment}}\n',
151	    });
152	
153	    const config: BuildConfig = {
154	      suites: { 'test-suite': suiteConfig },
155	      targets: ['vscode'],
156	      variables: { environment: 'staging' },
157	    };
158	
159	    const result = await renderPersona(yamlPath, suiteConfig, config);
160	
161	    expect(result.content).toContain('env: staging');
162	  });
163	
164	  it('renders multiple BuildConfig.variables values when all are unreferenced by higher layers', async () => {
165	    const { yamlPath, suiteConfig } = await createMinimalSuite({
166	      contentMd: '# {{name}}\na: {{alpha}}\nb: {{beta}}\n',
167	    });
168	
169	    const config: BuildConfig = {
170	      suites: { 'test-suite': suiteConfig },
171	      targets: ['vscode'],
172	      variables: { alpha: 'first', beta: 'second' },
173	    };
174	
175	    const result = await renderPersona(yamlPath, suiteConfig, config);
176	
177	    expect(result.content).toContain('a: first');
178	    expect(result.content).toContain('b: second');
179	  });
180	
181	  it('renders gracefully when BuildConfig.variables is absent (no-op, backward compat)', async () => {
182	    const { yamlPath, suiteConfig } = await createMinimalSuite({
183	      contentMd: '# {{name}}\n',
184	    });
185	
186	    const config: BuildConfig = {
187	      suites: { 'test-suite': suiteConfig },
188	      targets: ['vscode'],
189	      // no variables field
190	    };
191	
192	    const result = await renderPersona(yamlPath, suiteConfig, config);
193	
194	    expect(result.content).toContain('Test Agent');
195	  });
196	});
197	
198	// ---------------------------------------------------------------------------
199	// AC-2: SuiteConfig.variables values override BuildConfig.variables for the
200	//        same key.
201	// ---------------------------------------------------------------------------
202	
203	describe('AC-2 — SuiteConfig.variables overrides BuildConfig.variables for the same key', () => {
204	  it('suite-level value wins over config-level value for the same key', async () => {
205	    const { yamlPath, suiteConfig } = await createMinimalSuite({
206	      contentMd: '# {{name}}\ntier: {{tier}}\n',
207	    });
208	
209	    suiteConfig.variables = { tier: 'suite-value' };
210	
211	    const config: BuildConfig = {
212	      suites: { 'test-suite': suiteConfig },
213	      targets: ['vscode'],
214	      variables: { tier: 'config-value' },
215	    };
216	
217	    const result = await renderPersona(yamlPath, suiteConfig, config);
218	
219	    expect(result.content).toContain('tier: suite-value');
220	    expect(result.content).not.toContain('config-value');
221	  });
222	
223	  it('config-level key not shadowed by suite still appears in the output', async () => {
224	    const { yamlPath, suiteConfig } = await createMinimalSuite({
225	      contentMd: '# {{name}}\nconfig_only: {{config_only}}\nsuite_only: {{suite_only}}\n',
226	    });
227	
228	    suiteConfig.variables = { suite_only: 'from-suite' };
229	
230	    const config: BuildConfig = {
231	      suites: { 'test-suite': suiteConfig },
232	      targets: ['vscode'],
233	      variables: { config_only: 'from-config' },
234	    };
235	
236	    const result = await renderPersona(yamlPath, suiteConfig, config);
237	
238	    expect(result.content).toContain('config_only: from-config');
239	    expect(result.content).toContain('suite_only: from-suite');
240	  });
241	});
242	
243	// ---------------------------------------------------------------------------
244	// AC-3: Persona YAML values override both SuiteConfig.variables and
245	//        BuildConfig.variables for the same key.
246	// ---------------------------------------------------------------------------
247	
248	describe('AC-3 — persona YAML values override both SuiteConfig.variables and BuildConfig.variables', () => {
249	  it('persona YAML overrides BuildConfig.variables for the same key', async () => {
250	    const { yamlPath, suiteConfig } = await createMinimalSuite({
251	      personaYaml:
252	        'name: Test Agent\nvs_file_name: agent.agent.md\ncc_file_name: agent.md\nmy_key: from_persona\n',
253	      contentMd: '# {{name}}\nval: {{my_key}}\n',
254	    });
255	
256	    const config: BuildConfig = {
257	      suites: { 'test-suite': suiteConfig },
258	      targets: ['vscode'],
259	      variables: { my_key: 'from_config' },
260	    };
261	
262	    const result = await renderPersona(yamlPath, suiteConfig, config);
263	
264	    expect(result.content).toContain('val: from_persona');
265	    expect(result.content).not.toContain('from_config');
266	  });
267	
268	  it('persona YAML overrides SuiteConfig.variables for the same key', async () => {
269	    const { yamlPath, suiteConfig } = await createMinimalSuite({
270	      personaYaml:
271	        'name: Test Agent\nvs_file_name: agent.agent.md\ncc_file_name: agent.md\nmy_key: from_persona\n',
272	      contentMd: '# {{name}}\nval: {{my_key}}\n',
273	    });
274	
275	    suiteConfig.variables = { my_key: 'from_suite' };
276	
277	    const config: BuildConfig = {
278	      suites: { 'test-suite': suiteConfig },
279	      targets: ['vscode'],
280	    };
281	
282	    const result = await renderPersona(yamlPath, suiteConfig, config);
283	
284	    expect(result.content).toContain('val: from_persona');
285	    expect(result.content).not.toContain('from_suite');
286	  });
287	
288	  it('full three-layer chain — persona wins over suite and config for the same key', async () => {
289	    const { yamlPath, suiteConfig } = await createMinimalSuite({
290	      personaYaml:
291	        'name: Test Agent\nvs_file_name: agent.agent.md\ncc_file_name: agent.md\nresolution: persona\n',
292	      contentMd: '# {{name}}\nresolution: {{resolution}}\n',
293	    });
294	
295	    suiteConfig.variables = { resolution: 'suite' };
296	
297	    const config: BuildConfig = {
298	      suites: { 'test-suite': suiteConfig },
299	      targets: ['vscode'],
300	      variables: { resolution: 'config' },

301	    };
302	
303	    const result = await renderPersona(yamlPath, suiteConfig, config);
304	
305	    expect(result.content).toContain('resolution: persona');
306	    expect(result.content).not.toContain('resolution: suite');
307	    expect(result.content).not.toContain('resolution: config');
308	  });
309	});
310	
311	// ---------------------------------------------------------------------------
312	// AC-4: _shared.yaml values override BuildConfig.variables (but are
313	//        overridden by persona YAML).
314	// ---------------------------------------------------------------------------
315	
316	describe('AC-4 — _shared.yaml values override BuildConfig.variables but are overridden by persona YAML', () => {
317	  it('_shared.yaml value wins over BuildConfig.variables for the same key', async () => {
318	    const { yamlPath, suiteConfig } = await createMinimalSuite({
319	      sharedYaml: 'default_version: "1.0.0"\nenv: from_shared\n',
320	      contentMd: '# {{name}}\nenv: {{env}}\n',
321	    });
322	
323	    const config: BuildConfig = {
324	      suites: { 'test-suite': suiteConfig },
325	      targets: ['vscode'],
326	      variables: { env: 'from_config' },
327	    };
328	
329	    // Pass the shared values directly — same as what buildSuite() supplies to buildPersona()
330	    const result = await renderPersona(yamlPath, suiteConfig, config, {
331	      default_version: '1.0.0',
332	      env: 'from_shared',
333	    });
334	
335	    expect(result.content).toContain('env: from_shared');
336	    expect(result.content).not.toContain('from_config');
337	  });
338	
339	  it('persona YAML overrides _shared.yaml for the same key', async () => {
340	    const { yamlPath, suiteConfig } = await createMinimalSuite({
341	      sharedYaml: 'default_version: "1.0.0"\nenv: from_shared\n',
342	      personaYaml:
343	        'name: Test Agent\nvs_file_name: agent.agent.md\ncc_file_name: agent.md\nenv: from_persona\n',
344	      contentMd: '# {{name}}\nenv: {{env}}\n',
345	    });
346	
347	    const config: BuildConfig = {
348	      suites: { 'test-suite': suiteConfig },
349	      targets: ['vscode'],
350	      variables: { env: 'from_config' },
351	    };
352	
353	    const result = await renderPersona(yamlPath, suiteConfig, config, {
354	      default_version: '1.0.0',
355	      env: 'from_shared',
356	    });
357	
358	    expect(result.content).toContain('env: from_persona');
359	    expect(result.content).not.toContain('from_shared');
360	    expect(result.content).not.toContain('from_config');
361	  });
362	
363	  it('end-to-end via buildSuite(): _shared.yaml overrides BuildConfig.variables', async () => {
364	    const { suiteConfig } = await createMinimalSuite({
365	      sharedYaml: 'default_version: "1.0.0"\nsource: from_shared\n',
366	      contentMd: '# {{name}}\nsource: {{source}}\n',
367	    });
368	
369	    const config: BuildConfig = {
370	      suites: { 'test-suite': suiteConfig },
371	      targets: ['vscode'],
372	      variables: { source: 'from_config' },
373	    };
374	
375	    const results = await buildSuite('test-suite', suiteConfig, config, [], 'vscode');
376	
377	    expect(results).toHaveLength(1);
378	    expect(results[0].content).toContain('source: from_shared');
379	    expect(results[0].content).not.toContain('from_config');
380	  });
381	});
382	
383	// ---------------------------------------------------------------------------
384	// AC-5: BuildConfig.partials entries are present in the rendered template
385	//        output.
386	// ---------------------------------------------------------------------------
387	
388	describe('AC-5 — BuildConfig.partials entries appear in rendered output', () => {
389	  it('renders a partial defined in BuildConfig.partials when referenced in content', async () => {
390	    const { suiteConfig } = await createMinimalSuite({
391	      contentMd: '# {{name}}\n{{> disclaimer}}\n',
392	    });
393	
394	    const config: BuildConfig = {
395	      suites: { 'test-suite': suiteConfig },
396	      targets: ['vscode'],
397	      partials: { disclaimer: 'This is a config-level disclaimer.' },
398	    };
399	
400	    const results = await buildSuite('test-suite', suiteConfig, config, [], 'vscode');
401	
402	    expect(results).toHaveLength(1);
403	    expect(results[0].content).toContain('This is a config-level disclaimer.');
404	  });
405	
406	  it('renders multiple BuildConfig.partials in a single persona output', async () => {
407	    const { suiteConfig } = await createMinimalSuite({
408	      contentMd: '{{> header}}\n\n# {{name}}\n\n{{> footer}}\n',
409	    });
410	
411	    const config: BuildConfig = {
412	      suites: { 'test-suite': suiteConfig },
413	      targets: ['vscode'],
414	      partials: {
415	        header: 'Config header.',
416	        footer: 'Config footer.',
417	      },
418	    };
419	
420	    const results = await buildSuite('test-suite', suiteConfig, config, [], 'vscode');
421	
422	    expect(results[0].content).toContain('Config header.');
423	    expect(results[0].content).toContain('Config footer.');
424	  });
425	
426	  it('config partial that has no file-based counterpart is still rendered', async () => {
427	    const { suiteConfig } = await createMinimalSuite({
428	      // suite has a file partial named "greeting"; "info" comes only from config
429	      suitePartials: { greeting: 'File-based greeting.' },
430	      contentMd: '{{> greeting}}\n{{> info}}\n',
431	    });
432	
433	    const config: BuildConfig = {
434	      suites: { 'test-suite': suiteConfig },
435	      targets: ['vscode'],
436	      partials: { info: 'Config-only info block.' },
437	    };
438	
439	    const results = await buildSuite('test-suite', suiteConfig, config, [], 'vscode');
440	
441	    expect(results[0].content).toContain('Config-only info block.');
442	    // The file-based greeting should also still be present
443	    expect(results[0].content).toContain('File-based greeting.');
444	  });
445	});
