447	// ---------------------------------------------------------------------------
448	// AC-6: File-based partials with the same stem name override BuildConfig.partials.
449	// ---------------------------------------------------------------------------
450	
451	describe('AC-6 — file-based partials override BuildConfig.partials for the same stem name', () => {
452	  it('suite-local file partial wins over BuildConfig.partials entry with the same key', async () => {
453	    const { suiteConfig } = await createMinimalSuite({
454	      suitePartials: { greeting: 'Suite-local greeting (file).' },
455	      contentMd: '{{> greeting}}\n',
456	    });
457	
458	    const config: BuildConfig = {
459	      suites: { 'test-suite': suiteConfig },
460	      targets: ['vscode'],
461	      partials: { greeting: 'Config-level greeting.' },
462	    };
463	
464	    const results = await buildSuite('test-suite', suiteConfig, config, [], 'vscode');
465	
466	    expect(results[0].content).toContain('Suite-local greeting (file).');
467	    expect(results[0].content).not.toContain('Config-level greeting.');
468	  });
469	
470	  it('shared file partial wins over BuildConfig.partials entry with the same key', async () => {
471	    // Put the shared partial in a temp shared-partials directory
472	    const sharedPartialsDir = path.join(testTmpDir, 'shared-partials');
473	    await mkdir(sharedPartialsDir, { recursive: true });
474	    await writeFile(path.join(sharedPartialsDir, 'greeting.md'), 'Shared file greeting.');
475	
476	    const { suiteConfig } = await createMinimalSuite({
477	      contentMd: '{{> greeting}}\n',
478	    });
479	
480	    const config: BuildConfig = {
481	      suites: { 'test-suite': suiteConfig },
482	      targets: ['vscode'],
483	      sharedPartialsDir,
